#!/usr/bin/env python3
"""
╔══════════════════════════════════════════════════════════════════╗
║          ATLAS — Sprint 8 Installer (Self-Contained)            ║
║                                                                  ║
║  Run once from your project root (folder with atlas_omega.py):  ║
║      python sprint8_install.py                                   ║
║                                                                  ║
║  Installs:                                                       ║
║    M7  global_liquidity_scraper.py  (new agent)                 ║
║    D5  dark_pool_scraper.py         (new agent)                 ║
║    D10 sector_rotation_scraper.py   (new agent)                 ║
║    M2  inflation_scraper.py         (patched + mock fallback)   ║
║    3   new pytest files                                          ║
║    Updated AGENT_REGISTRY.md  (22 Built | 93 Pending)          ║
║    atlas_omega.py  (Sprint 8 — 3 new DC_INTENTs wired)         ║
║    6   pre-generated data_cache JSON files                       ║
╚══════════════════════════════════════════════════════════════════╝
"""

import base64, json, sys
from pathlib import Path

for _stream in (sys.stdout, sys.stderr):
    if hasattr(_stream, "reconfigure"):
        _stream.reconfigure(encoding="utf-8", errors="replace")

ROOT = Path(__file__).resolve().parent
OMEGA = ROOT / "atlas_omega.py"

def check_root():
    if not OMEGA.exists():
        print(f"\n❌  ERROR: atlas_omega.py not found in {ROOT}")
        print("    Run from your project root (where atlas_omega.py lives).")
        sys.exit(1)
    print(f"✅  Project root confirmed: {ROOT}")

FILES = {
  "atlas_agents/macro/global_liquidity/__init__.py": "IyBNNyDigJQgR2xvYmFsIExpcXVpZGl0eSBNb25pdG9yIHwgTWFjcm8gRGl2aXNpb24K",
  "atlas_agents/macro/global_liquidity/global_liquidity_scraper.py": "",
  "atlas_agents/trading/dark_pool/dark_pool_scraper.py": "",
  "atlas_agents/intelligence/sector_rotation/sector_rotation_scraper.py": "",
  "atlas_agents/macro/inflation/inflation_scraper.py": "",
  "atlas_agents/AGENT_REGISTRY.md": "",
  "tests/test_global_liquidity.py": "",
  "tests/test_d5_dark_pool_scraper.py": "",
  "tests/test_d10_sector_rotation.py": "",
  "data_cache/global_liquidity_latest.json": "",
  "data_cache/dark_pool_latest.json": "",
  "data_cache/sector_rotation_latest.json": "",
  "data_cache/cpi_latest.json": "",
  "data_cache/fed_watch_latest.json": "",
  "data_cache/bond_yields_latest.json": "",
  "atlas_omega.py": ""
}

def write_files():
    for rel_path, b64 in FILES.items():
        dest = ROOT / rel_path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(base64.b64decode(b64))
        print(f"  ✔  {rel_path}")

def verify():
    print("\n🔍  Verifying cache files...")
    cache = ROOT / "data_cache"
    expected = [
        "global_liquidity_latest.json", "dark_pool_latest.json",
        "sector_rotation_latest.json",  "cpi_latest.json",
        "fed_watch_latest.json",         "bond_yields_latest.json",
    ]
    all_ok = True
    for fname in expected:
        p = cache / fname
        if p.exists():
            try:
                data = json.loads(p.read_text())
                print(f"  ✅  {fname}  ({len(data)} top-level keys)")
            except Exception as e:
                print(f"  ⚠️  {fname}  — parse error: {e}")
                all_ok = False
        else:
            print(f"  ❌  {fname}  — MISSING")
            all_ok = False
    return all_ok

def main():
    print("\n" + "="*62)
    print("  🚀  ATLAS Sprint 8 Installer")
    print("="*62)
    check_root()
    print(f"\n📂  Writing {len(FILES)} Sprint 8 files...")
    write_files()
    ok = verify()
    print("\n" + "="*62)
    print("  ✅  Install COMPLETE" if ok else "  ⚠️   Install finished with warnings")
    print("="*62)
    print("\n📋  Run your tests:")
    print("     python -m pytest tests/test_global_liquidity.py \\")
    print("                      tests/test_d5_dark_pool_scraper.py \\")
    print("                      tests/test_d10_sector_rotation.py -v")
    print("\n     python -m pytest tests/ -q   # full suite")
    print("\n📊  Registry: 22 Built | 93 Pending | 115 Total\n")

if __name__ == "__main__":
    main()
